n("מקונן", "מקונן הוא שם באמהרית, השפה של אתיופיה, ופירושו כנראה קצין או אדם נכבד. השם נפוץ באתיופיה, והוא הגיע לארץ עם העלייה של יהודי אתיופיה. השם ניתן לבנים, והוא נדיר. הצליל שלו מכובד ושונה מהשמות העבריים.", [])
n("גינת", "גינת הוא שם עברי מהמילה גינה, מקום קטן של פרחים וצמחים. השם נשמע רך וירוק, והוא ניתן לבנות. גינת הוא גם שם של שכונות ושל רחובות בארץ. קרובים אליו השמות גנית וגני, והוא נדיר.", ["גנית", "גני"])
n("פיי", "פיי הוא שם אנגלי שבא מהמילה פיי, פיה, יצור קסום מהאגדות. השם היה נפוץ באנגליה ובאמריקה בתחילת המאה העשרים. בארץ השם נדיר מאוד, והוא ניתן לבנות. הצליל שלו קצר וקליל, ויש בו קסם של סיפורי ילדים.", [])
n("דוברת", "דוברת הוא שם עברי נדיר מהמילה דיבור, ופירושו מי שמדברת. דוברת היא גם שם של קיבוץ בעמק יזרעאל, שנקרא על שם עיר עתיקה. השם ניתן לבנות, והוא קרוב בצליל לשמות דבורה ודברת.", ["דבורה", "דברת"])
n("יעד", "יעד הוא שם עברי מהמילה יעד, מטרה שאליה הולכים. השם נשמע ממוקד וחזק, והוא נדיר. השם ניתן לבנים. יעד הוא גם שם של יישוב בגליל. קרוב אליו בצליל השם יועד.", ["יועד"])
n("אבידור", "אבידור הוא שם עברי חדש שבנוי מהמילים אבי ודור, ופירושו אבי הוא הדור. השם נשמע מכובד ונדיר. השם ניתן לבנים. הוא קרוב לשמות כמו אבידן ואביעד, שבנויים באותה דרך.", ["אבידן", "דור"])
n("אליעז", "אליעז הוא שם עברי חדש שבנוי מהמילים אלי ועז, ופירושו האל שלי הוא כוח. מאותה מילה באים גם השמות עוז ועוזיאל. השם ניתן לבנים, והוא נדיר. קרוב אליו מאוד השם אליעוז.", ["אליעוז", "עוז"])
n("מצדה", "מצדה הוא שם של המבצר על צוק גבוה במדבר יהודה, ליד ים המלח. לפי יוספוס, המורדים במצדה החזיקו מעמד מול הרומאים עד הסוף. המקום הפך לסמל של עמידה. השם ניתן לבנות, והוא נדיר מאוד.", [])
n("גיליה", "גיליה הוא שם עברי שבנוי מהמילים גיל ויה, ופירושו השמחה של אלוהים. מאותה מילה באים גם השמות המוכרים גיל, גילה וגילי. השם ניתן לבנות, והוא נדיר. הוא נשמע שמח וקליל.", ["גילה", "גיל"])
n("זילפה", "זילפה היא שפחתה של לאה. בספר בראשית מסופר שלאה נתנה את זילפה ליעקב, וזילפה ילדה את גד ואת אשר, שהיו לשניים משבטי ישראל. השם ניתן לבנות, והוא נדיר מאוד היום.", ["בלהה"])
n("זהורית", "זהורית היא צבע אדום בוהק, וגם בד אדום. השם קשור למילה זוהר, אור. השם ניתן לבנות, והוא נדיר. הוא נשמע עתיק ובוהק, וקרובים אליו השמות זוהר וזוהרה.", ["זוהר", "זוהרה"])
n("דינור", "דינור הוא שם ארמי שבנוי מהמילים די ונור, ופירושו של אש. במסורת נהר דינור הוא נהר של אש לפני כסא הכבוד. השם ניתן לבנות, והוא נדיר. הוא נשמע עתיק וחזק.", [])
n("אודיל", "אודיל הוא שם צרפתי ממקור גרמני, שפירושו כנראה עושר. השם מוכר מהבלט אגם הברבורים, שבו אודיל היא הברבור השחור. בארץ השם נדיר, והוא ניתן לבנות. קרובים אליו השמות אודט ואדל.", ["אודט", "אדל"])
n("מקסין", "מקסין היא הצורה הנשית הצרפתית של מקסים, שם לטיני שפירושו הגדול ביותר. השם היה נפוץ בצרפת ובאמריקה באמצע המאה העשרים. בארץ השם נדיר, והוא ניתן לבנות.", ["מקסים"])
n("וולטר", "וולטר הוא שם בינלאומי ממקור גרמני, שבנוי מהמילים שלטון וצבא, ופירושו מנהיג הצבא. השם היה נפוץ בגרמניה ובאנגליה. בארץ הוא נדיר, והוא ניתן לבנים.", [])
n("פלור", "פלור היא המילה הצרפתית לפרח. השם קצר ועדין, והוא נפוץ בצרפת ובבלגיה. בארץ השם נדיר, והוא ניתן לבנות. קרוב אליו השם פלורה, ושמות עבריים של פרחים כמו פרחיה.", ["פלורה"])
n("נופיה", "נופיה הוא שם עברי שבנוי מהמילים נוף ויה, ופירושו הנוף של אלוהים. השם נשמע רחב ופתוח, והוא ניתן לבנות. הוא נדיר, וקרוב אליו השם נופית.", ["נופית"])
n("שפי", "שפי הוא צורת חיבה של שפרה, אחת המיילדות במצרים, ששמה פירושו יפה. בעברית השם קשור גם למילה שפיות. השם ניתן גם לבנים וגם לבנות, והוא נדיר. הצליל שלו קצר וחם.", ["שפרה"])
n("קרן-אור", "קרן־אור הוא שם עברי שבנוי מהמילים קרן ואור, ופירושו קרן של אור. השם קרוב לשמות קרן ואור, והוא נשמע בהיר. השם ניתן לבנות, והוא נדיר.", ["קרן", "אור"])
n("פאולו", "פאולו היא הצורה האיטלקית והפורטוגזית של פאולוס, שם לטיני שפירושו קטן. השם נפוץ באיטליה, בפורטוגל ובברזיל. בארץ השם נדיר, והוא ניתן לבנים. קרובה אליו צורת הנקבה פאולה.", ["פאולה"])
n("ראות", "ראות הוא שם עברי חדש מהמילה ראייה, היכולת לראות למרחוק. השם נשמע פתוח וחכם. השם ניתן לבנות, והוא נדיר. קרובים אליו השמות רואי ויוראי.", ["רואי"])
n("רמונה", "רמונה הוא שם ספרדי, הצורה הנשית של רמון, שם גרמני שפירושו מגן חכם. בעברית השם נשמע קרוב לרימון ולרימונה. השם ניתן לבנות, והוא נדיר בארץ.", ["רימונה"])
n("מרטינה", "מרטינה היא הצורה הנשית של מרטין, שם לטיני שקשור למרס, אל המלחמה הרומי. השם נפוץ באיטליה, בספרד ובצ׳כיה. בארץ השם נדיר, והוא ניתן לבנות.", ["מרטין"])
n("אשכר", "אשכר היא מילה עברית עתיקה למנחה ולמתנה. השם נשמע עתיק ומיוחד, והוא ניתן לבנות. אשכר הוא שם נדיר, אבל יש בו תודה על מתנה גדולה, הילדה.", [])
n("זמר", "זמר הוא שם עברי מהמילה זמר, שיר ומנגינה. מאותה מילה באים גם השמות זמיר וזמירה. השם ניתן גם לבנים וגם לבנות, והוא נדיר. הוא נשמע מוזיקלי וקצר, ויש בו שמחה של שירה.", ["זמיר", "זמירה"])
n("אשכול", "אשכול הוא שם עברי מהמילה אשכול, ענבים על ענף אחד. בספר במדבר המרגלים מביאים מנחל אשכול אשכול ענבים כל כך גדול, שנשאו אותו שניים במוט. השם ניתן לבנים, והוא נדיר.", [])
n("גרמי", "גרמי הוא כנראה כתיב של ג׳רמי, הצורה האנגלית של ירמיהו, שפירושו ה׳ ירומם. השם ניתן לבנים, והוא נדיר. בכתיב הזה הוא נשמע קרוב למילים עבריות.", ["ג'רמי", "ירמיהו"])
n("דדי", "דדי הוא צורת חיבה של דוד, השם של המלך המשורר. השם דוד פירושו אהוב. דדי היה מוכר בארץ בשנות החמישים והשישים, והוא ניתן לבנים. קרובים אליו השמות דודי ודודו.", ["דוד", "דודי"])
n("תמירה", "תמירה הוא שם עברי מהמילה תמיר, גבוה וזקוף, כמו עץ התמר. מאותה מילה באים גם השמות תמר ותמיר. השם ניתן לבנות, והוא נדיר. הוא נשמע גבוה וגאה.", ["תמר", "תמיר"])
n("חיותה", "חיותה היא צורת חיבה ביידיש של חיה, שם שפירושו חיים. ביידיש נבנו צורות חיבה רבות של חיה, כמו חייקה וחיותה. השם ניתן לבנות, והוא נדיר היום.", ["חיה"])
n("טלמור", "טלמור הוא שם עברי חדש שבנוי מהמילים טל ומור, צמח בושם. השם נשמע רענן וריחני. השם ניתן גם לבנים וגם לבנות, והוא נדיר. קרובים אליו השמות טל ומור.", ["טל", "מור"])
n("אנוש", "אנוש הוא שם מקראי מהמילה אנוש, בן אדם. בספר בראשית אנוש הוא בנו של שת ונכדו של אדם, ונאמר שבימיו החלו לקרוא בשם ה׳. השם ניתן לבנים, והוא נדיר.", [])
n("אימי", "אימי הוא כנראה כתיב של איימי, שם אנגלי שבא מהמילה הצרפתית אמה, אהובה. בעברית הצליל שלו קרוב למילה אמי. השם ניתן לבנות, והוא נדיר.", ["איימי"])
n("משכית", "משכית היא מילה עברית עתיקה לקישוט, לתמונה או לתכשיט. משכית הייתה גם שם של חברה ישראלית שעיצבה בגדים ותכשיטים בשנות החמישים והשישים. השם ניתן לבנות, והוא נדיר.", [])
n("יואש", "יואש הוא שם מקראי שפירושו כנראה ה׳ נתן. בספר שופטים יואש הוא אביו של גדעון, והיה גם מלך יהודה בשם יואש. השם ניתן לבנים, והוא נדיר. קרוב אליו השם יהואש.", ["יהואש", "יאשיהו"])
n("אנגל", "אנגל היא המילה האנגלית למלאך. בשפות של אירופה השם מוכר בצורות כמו אנג׳ל ואנחל. השם ניתן גם לבנים וגם לבנות, והוא נדיר בארץ. הוא נשמע רך ושמימי.", [])
n("שבח", "שבח הוא שם עברי מהמילה שבח, תהילה והלל. השם היה נפוץ בעיקר בקהילות של יהודי תימן. השם ניתן לבנים, והוא נדיר היום. הוא מביע הודיה ותהילה.", [])
n("דוריאל", "דוריאל הוא שם עברי חדש שבנוי מהמילים דור ואל, ופירושו הדור של אלוהים. השם קרוב לשמות דור, דוראל ודורית. השם ניתן גם לבנים וגם לבנות, והוא נדיר.", ["דור", "דוראל"])
n("אלסיה", "אלסיה הוא שם איטלקי, צורה של אלכסנדרה, שפירושו מגינה על בני אדם. השם נפוץ מאוד באיטליה בשנים האחרונות. בארץ השם נדיר, והוא ניתן לבנות.", ["אליסיה"])
n("מלה", "מלה הוא כתיב של מילה, שם עברי שבא מהמילה מילה, דיבור או משפט. השם קצר ופשוט. השם ניתן לבנות, והוא נדיר. בשפות של אירופה הוא נשמע גם כמו מילה, צורה של אמיליה.", ["מילה"])
n("עלית", "עלית הוא כתיב של עילית, שם עברי מהמילה עילוי, הטובה ביותר. בארץ עלית מוכרת גם כשם של חברת ממתקים. השם ניתן לבנות, והוא נדיר.", ["עילית", "עילי"])
n("בינת", "בינת הוא שם עברי מהמילה בינה, תבונה והבנה. השם נשמע חכם ורך. השם ניתן לבנות, והוא נדיר. קרובים אליו השמות בינה ובניה.", ["בינה"])
n("צחית", "צחית הוא שם עברי מהמילה צח, צלול ובהיר. השם נשמע טהור ושקט. השם ניתן לבנות, והוא נדיר. קרובים אליו השמות צח וצחי.", ["צח", "צחי"])
n("אבינדב", "אבינדב הוא שם מקראי שבנוי מהמילים אבי ונדב, ופירושו אבי נדיב. בספר שמואל אבינדב הוא אחד מאחיו של דוד, שישי ראה לפני שמואל לפני שנבחר דוד. השם ניתן לבנים, והוא נדיר.", ["נדב"])
n("יאשיהו", "יאשיהו הוא שם מקראי. יאשיהו היה מלך יהודה, ובספר מלכים מסופר שבימיו נמצא ספר התורה במקדש, והוא עשה רפורמה גדולה בעבודת ה׳. השם ניתן לבנים, והוא נפוץ בעיקר בקהילות דתיות.", ["יואש"])
n("פרננדה", "פרננדה היא הצורה הנשית של פרננדו, שם ספרדי ממקור גרמני שפירושו אמיץ במסע. השם נפוץ בספרד ובאמריקה הלטינית. בארץ הוא נדיר, והוא ניתן לבנות.", [])
n("מגל", "מגל הוא כלי עבודה חד ומעוקל לקציר תבואה. השם עברי, והוא מביא תמונה של שדה ושל קציר. מגל הוא גם שם של קיבוץ בשרון. השם ניתן גם לבנים וגם לבנות, והוא נדיר.", [])
n("טל-אור", "טל־אור הוא שם עברי חדש שבנוי מהמילים טל ואור, ופירושו טל של אור. השם נשמע רענן ובהיר. השם ניתן גם לבנים וגם לבנות, והוא נדיר. קרובים אליו השמות טל ואור.", ["טל", "אור"])
n("אלפרדו", "אלפרדו הוא שם איטלקי וספרדי ממקור אנגלי עתיק, שפירושו יועץ של האלפים. השם נפוץ באיטליה ובאמריקה הלטינית. בארץ הוא נדיר, והוא ניתן לבנים.", [])
n("צופנת", "צופנת הוא שם עברי נדיר מהמילה צפון, נסתר ושמור. השם נשמע מסתורי ועדין. השם ניתן לבנות, וקרובים אליו השמות צפנת וצפניה.", ["צפנת", "צפניה"])
n("לירוז", "לירוז הוא שם עברי חדש שבנוי מהמילים לי ורז, ופירושו יש לי סוד. השם שייך לקבוצה של שמות כמו לירז וליאור. השם ניתן לבנות, והוא נדיר.", ["לירז"])
n("בושמת", "בושמת הוא כתיב של בשמת, שם עברי מהמילה בושם, ריח טוב. השם עתיק ומיוחד, והוא ניתן לבנות. בכתיב הזה המילה בושם בולטת יותר. השם נדיר.", ["בשמת"])
